CREATE TABLE students (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name VARCHAR(80) NOT NULL, email TEXT UNIQUE, marks INTEGER CHECK (marks BETWEEN 0 AND 100));
CREATE TABLE courses (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE enrollments (student_id BIGINT REFERENCES students(id) ON DELETE CASCADE, course_id INTEGER REFERENCES courses(id), enrolled_on DATE NOT NULL, PRIMARY KEY (student_id, course_id));
